// Verifies X-Retell-Signature. Format: "v=<unix ms>,d=<hex hmac>"
// digest = HMAC-SHA256(rawBody + timestamp, RETELL_API_KEY), timestamp must be within 5 minutes,
// compared in constant time. Source: https://docs.retellai.com/features/secure-webhook
// Requires: NODE_FUNCTION_ALLOW_BUILTIN=crypto and the Webhook node option "Raw Body" (binary property "data").
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const sigHeader = String(headers['x-retell-signature'] || '');
const apiKey = $env.RETELL_API_KEY || '';
let raw;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  // Fallback only if raw body is unavailable; a re-serialized body may not match the signed bytes.
  raw = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body ?? {});
}
let verified = false;
let reason = 'missing_signature';
if (!apiKey) {
  reason = 'missing_api_key';
} else if (sigHeader) {
  const parts = {};
  for (const seg of sigHeader.split(',')) {
    const i = seg.indexOf('=');
    if (i > 0) parts[seg.slice(0, i).trim()] = seg.slice(i + 1).trim();
  }
  const ts = parts.v;
  const given = parts.d;
  if (!ts || !given) {
    reason = 'malformed_signature';
  } else if (Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000) {
    reason = 'stale_timestamp';
  } else {
    const expected = crypto.createHmac('sha256', apiKey).update(raw + ts).digest('hex');
    const a = Buffer.from(expected, 'utf8');
    const b = Buffer.from(given, 'utf8');
    verified = a.length === b.length && crypto.timingSafeEqual(a, b);
    reason = verified ? 'ok' : 'digest_mismatch';
  }
}
let body = item.json.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
return [{ json: { verified, reason, body: body ?? {}, headers } }];

// ---- shared helpers (duplicated in each workflow on purpose: n8n Code nodes cannot import) ----
const crypto = require('crypto');
const TZ = $env.PRACTICE_TZ || 'America/New_York';
const SALT = $env.PATIENT_HASH_SALT || '';
const envJson = (k) => { try { return JSON.parse($env[k] || '{}'); } catch (e) { return {}; } };
const sha256 = (s) => crypto.createHash('sha256').update(String(s)).digest('hex');
const patientRef = (id) => (id === null || id === undefined || id === '') ? null : sha256(String(id) + SALT);
const fmt = (d, opts) => new Intl.DateTimeFormat('en-US', Object.assign({ timeZone: TZ }, opts)).format(d);
const ordinal = (n) => n + ((n % 10 === 1 && n !== 11) ? 'st' : (n % 10 === 2 && n !== 12) ? 'nd' : (n % 10 === 3 && n !== 13) ? 'rd' : 'th');
const sayWhen = (iso) => { const d = new Date(iso); return fmt(d, { weekday: 'long' }) + ' the ' + ordinal(Number(fmt(d, { day: 'numeric' }))) + ' at ' + fmt(d, { hour: 'numeric', minute: '2-digit' }); };
const providerFirst = (id, fallbackName) => {
  const names = envJson('NEXHEALTH_PROVIDER_NAMES');
  if (id !== null && id !== undefined && names[String(id)]) return names[String(id)];
  if (fallbackName) { const parts = String(fallbackName).replace(/^(dr\.?|doctor)\s+/i, '').trim().split(/\s+/); return parts.length ? 'Dr. ' + parts[parts.length - 1] : null; }
  return null;
};
const e164 = (p) => { if (!p) return null; let d = String(p).replace(/[^\d+]/g, ''); if (d.startsWith('+')) return d; d = d.replace(/\D/g, ''); if (d.length === 10) return '+1' + d; if (d.length === 11 && d.startsWith('1')) return '+' + d; return d ? '+' + d : null; };
// ---- end helpers ----

// call_analyzed payload: { event, call: { call_id, direction, from_number, to_number, disconnection_reason,
//   retell_llm_dynamic_variables, call_analysis: { custom_analysis_data: { outcome, phi_beyond_scheduling_mentioned, sms_opt_in_given, ... } } } }
const body = $json.body || {};
const call = body.call || {};
const analysis = call.call_analysis || {};
const custom = analysis.custom_analysis_data || {};
const dyn = call.retell_llm_dynamic_variables || {};
const numMap = envJson('RETELL_LOCATION_NUMBERS');
const truthy = (v) => v === true || String(v).toLowerCase() === 'true';
const inbound = (call.direction || 'inbound') === 'inbound';
const practiceNumber = e164(inbound ? call.to_number : call.from_number);
const patientNumber = e164(inbound ? call.from_number : call.to_number);
const location = dyn.location || numMap[practiceNumber] || 'unknown';
const outcome = String(custom.outcome || 'unknown');
const smsOptIn = truthy(custom.sms_opt_in_given);
const optOut = truthy(custom.sms_opt_out_requested);          // verbal "don't text me" (TODO: add this boolean to post_call_analysis_data in the agent config)
const qaFlag = truthy(custom.phi_beyond_scheduling_mentioned);
const kinds = ['recording_notice', 'ai_disclosure'];
if (smsOptIn) kinds.push('sms_opt_in');
if (optOut) kinds.push('call_opt_out');
const phone_hash = sha256((patientNumber || 'unknown') + SALT);
const phone_last4 = patientNumber ? patientNumber.slice(-4) : '0000';
const sendSms = smsOptIn && !optOut && ['booked', 'rescheduled'].includes(outcome) && !!patientNumber && !!practiceNumber;
const sms_body = {
  from_number: practiceNumber,
  to_number: patientNumber,
  override_agent_id: $env.RETELL_SMS_AGENT_ID || undefined,
  metadata: { call_id: call.call_id || null, purpose: 'confirmation' },
  retell_llm_dynamic_variables: {
    practice_name: String($env.PRACTICE_NAME || ''),
    location: String(location),
    outcome,
    // TODO: add appointment_day / appointment_time to post_call_analysis_data so the SMS agent can quote them.
    appointment_day: String(custom.appointment_day || dyn.appointment_day || ''),
    appointment_time: String(custom.appointment_time || dyn.appointment_time || ''),
  },
};
return [{ json: {
  call_id: call.call_id || null,
  location: String(location),
  outcome,
  patient_ref: patientRef(custom.patient_id || dyn.patient_id || null),
  appointment_ref: custom.appointment_id ? String(custom.appointment_id) : null,
  detail: { qa_flag: qaFlag, direction: call.direction || null, disconnection_reason: call.disconnection_reason || null, sms_opt_in: smsOptIn, call_opt_out: optOut },
  phone_hash, phone_last4, kinds, script_ver: 'v1.0',
  send_sms: sendSms, opt_out: optOut, sms_body,
} }];
